function groupNames(dim,label){const kd=selSet("pp2ck",KINDSET),tm=selSet("pp2ct",teamList());return DIR.filter(d=>kd.includes(d.kind)&&(!d.team||tm.includes(d.team))&&(dim==="team"?d.team===label:dim==="fam"?rfam(d)===label:dim==="kind"?d.kind===label:dim==="skill"?(d.skills||[]).includes(label):true)).map(d=>d.name)}
const gagg=(dim,label)=>agg(groupNames(dim,label),"g:"+dim+":"+label+"|"+selSet("pp2ck",KINDSET).join(",")+"|"+selSet("pp2ct",teamList()).join(",")+"|"+DIR.length+"|"+(st.mv||0)+"|"+(st.ver||0));
function groupRows(dim){const kd=selSet("pp2ck",KINDSET),tm=selSet("pp2ct",teamList());const base=DIR.filter(d=>kd.includes(d.kind)&&(!d.team||tm.includes(d.team)));
 if(dim==="team")return teamList().filter(t=>tm.includes(t)).map(t=>[t,t]);if(dim==="fam")return ROLEFAMS.filter(f=>base.some(d=>rfam(d)===f)).map(f=>[f,f]);if(dim==="kind")return kd.map(k=>[k,KINDS[k]]);
 if(dim==="skill"){const c={};base.forEach(d=>(d.skills||[]).forEach(s=>c[s]=(c[s]||0)+1));return Object.entries(c).filter(x=>x[1]>=2).sort((a,b)=>b[1]-a[1]).slice(0,24).map(x=>[x[0],x[0]+" ("+x[1]+")"])}
 return []}
const cellVal=(A,w,wt)=>{const d=wt==="all"?A.tot[w]:A.T[wt][w];return A.cap[w]>.5?d/A.cap[w]:null};
const heatCell=(u,attrs,ov)=>`<button class="pp2-hc2${ov?" hid":""}${u>1.0001?" over":""}" style="--cc:var(${uCol(u)});--a:${u==null?24:u>1?Math.min(88,60+(u-1)*120):u>.85?58:u>=.5?36+(u-.5)*40:24}" ${attrs}></button>`;
