function heatTab(){const dim=CAP.heat,wt=CAP.wt;const dims=[["team","Team"],["fam","Role family"],["kind","Kind of worker"],["skill","Skill"],["person","Person"]];
 const sw=`<div class="pp2-bar"><div class="vsw glass" role="group" aria-label="Group rows by">${dims.map(d=>`<button class="${d[0]===dim?"on":""}" data-pp2-act="heatdim" data-a="${d[0]}" aria-pressed="${d[0]===dim}">${d[1]}</button>`).join("")}</div><label class="small">Show <select data-pp2-wt aria-label="Work type">${[["all","All work types"]].concat(WT.map(x=>[x[0],x[1]])).map(o=>`<option value="${o[0]}"${o[0]===wt?" selected":""}>${o[1]}</option>`).join("")}</select></label><button class="btn" data-pp2-act="capcsv">Export CSV</button></div>`;
 let rows;const lim=25+(CAP.pg.heat||0);
 if(dim==="person"){const nm=scopeNames().filter(n=>who(n)&&who(n).kind!=="msp").map(n=>({n,u:avgU(PM(n),0,11)})).sort((a,b)=>b.u-a.u);rows=nm.slice(0,lim).map(x=>{const m=PM(x.n);return {lab:x.n,sub:pc(x.u),node:`<span class="pp2-hl">${pchip(x.n)}</span>`,cells:[...Array(NWK)].map((_,w)=>heatCell(cellVal({cap:m.cap,tot:m.tot,T:m.T},w,wt),`data-pp2-act="cell" data-a="${E(x.n)}|${w}" title="${E(x.n)}, week of ${WK[w].lab}: ${pc(cellVal({cap:m.cap,tot:m.tot,T:m.T},w,wt))}" aria-label="${E(x.n)} week of ${WK[w].lab}"`,false)).join("")}});rows.more=nm.length>lim?nm.length-lim:0}
 else{rows=groupRows(dim).map(([k,l])=>{const A=gagg(dim,k);const gn=groupNames(dim,k).length;const o=dim==="skill"||dim==="kind"||dim==="fam"||dim==="team"?ovWeeks(groupNames(dim,k)):new Float32Array(NWK);return {lab:l,sub:pc(avgU(A,0,11)),node:`<button class="pp2-hl pp2-lnk" data-pp2-act="rgrp" data-a="${dim}|${E(k)}">${E(l)}</button>`,cells:[...Array(NWK)].map((_,w)=>{const u=cellVal(A,w,wt);return heatCell(u,`data-pp2-act="rcell" data-a="${dim}|${E(k)}|${w}" title="${E(l)}, week of ${WK[w].lab}: ${pc(u)}${o[w]?", "+o[w]+" "+(o[w]===1?"person":"people")+" over 100%":""}" aria-label="${E(l)} week of ${WK[w].lab}"`,(o[w]>=2||o[w]>=.12*gn)&&(u==null||u<=1.0001))}).join("")}})}
 const mons=`<div class="pp2-hmon">${MONTHS.map(m=>`<span style="grid-column:${m.w0+2}/span ${m.w1-m.w0+1}">${m.lab}</span>`).join("")}</div>`;
 return scopeBar()+sw+`<p class="story" data-role="story">${dim==="person"?"One row per person, busiest first. ":""}Each cell is one week, from the week of ${WK[0].lab} through ${WK[NWK-1].lab}. Red cells have more work than available hours. A <b>ringed</b> cell is a group that looks fine on average while at least one person in it is over 100%. Select a row name to see the people, a cell to see the week.</p>
 <div class="tscroll"><div class="pp2-heat2" style="--cols:${NWK}">${mons}${rows.map(r=>`<div class="pp2-hr2"><span class="pp2-hn2">${r.node}<small>${r.sub}</small></span>${r.cells}</div>`).join("")}</div></div>
 ${rows.more?`<button class="btn" data-pp2-act="heatmore">Show 25 more of ${rows.more}</button>`:""}${legend([["Under 50%","--p6"],["50% to 85%","--good-f"],["85% to 100%","--warn-f"],["Over 100% (striped)","--bad-f"],["No capacity","--faint"]])}<p class="muted small">Ringed cell means a group below 100% in total with someone over it. Percent is work hours divided by available hours after leave and holidays.</p>`}
