/* ---- leveling ---- */
function overWeeks(n,w0,w1){const m=PM(n),out=[];for(let w=w0;w<=w1;w++)if(m.cap[w]>.5&&m.util[w]>1.0001)out.push([w,m.tot[w]-m.cap[w]]);return out}
let FXN=1;
function levelOpts(n){const m=PM(n),r=m.r,ow=overWeeks(n,0,25);if(!ow.length)return null;const tot=ow.reduce((a,x)=>a+x[1],0),wA=ow[0][0],wB=ow[ow.length-1][0];
 const peers=DIR.filter(d=>(d.kind==="human"||d.kind==="contractor")&&d.team===r.team&&d.name!==n).map(d=>d.name);let best=null;
 peers.forEach(p=>{const pm=PM(p);let room=0;ow.forEach(([w,h])=>{room+=Math.min(h,m.T.proj[w],Math.max(0,pm.cap[w]*.88-pm.tot[w]))});if(!best||room>best.room)best={p,room}});
 const moved=best?best.room:0;const ag=DIR.filter(d=>d.kind==="ai").map(d=>({d,u:avgU(PM(d.name),0,25)})).sort((a,b)=>a.u-b.u)[0];
 const offH=ow.reduce((a,[w,h])=>a+Math.min(h,(m.T.req[w]+m.T.bau[w])*.35),0);const dh=ow.reduce((a,[w,h])=>a+Math.min(h,m.T.proj[w]),0);const rate=rateAvg();const fte=Math.max(.25,Math.ceil(Math.max(...ow.map(x=>x[1]))/40*4)/4);
 const dateOf=w=>isoOfWk(clamp(w,0,NWK-1));
 const opts=[
  {id:"move",t:best&&moved>0?"Move "+f1(moved)+" hours to "+best.p:"Move project work to a teammate",h:moved,cost:0,ok:moved>0,risk:best?"Needs "+best.p+" to agree. Skills match is checked against the team, not the task.":"No one in the team has room.",apply:()=>{const id="FX"+FXN++;ow.forEach(([w,h])=>{const pm=PM(best.p);const x=Math.min(h,m.T.proj[w],Math.max(0,pm.cap[w]*.88-pm.tot[w]));if(x>0.01){CAP.ov.push({fx:id,owner:n,type:"proj",w,h:-x});CAP.ov.push({fx:id,owner:best.p,type:"proj",w,h:x})}});return {id,t:"Moved project work from "+n+" to "+best.p}}},
  {id:"ctr",t:"Add a contractor for "+f1(fte)+" FTE",h:tot,cost:Math.round(tot*rate),ok:true,risk:"Takes about 2 weeks to onboard. About $"+fmt(tot*rate)+" at $"+rate+" an hour. Creates a resource request for approval.",apply:()=>{const id="FX"+FXN++;const q={id:"RQ"+(CAP.reqs.length+1),title:"Contractor to relieve "+n,team:r.team,role:rfam(r),kind:"contractor",skills:(r.skills||[]).slice(0,2),fte,from:dateOf(wA),to:dateOf(wB+1),status:"Resource manager",by:"Resource Agent",why:"Leveling "+n+": "+f1(tot)+" hours over capacity.",at:"2026-10-07",fx:id};CAP.reqs.unshift(q);ow.forEach(([w,h])=>{const x=Math.min(h,m.T.proj[w]);if(x>0)CAP.ov.push({fx:id,owner:n,type:"proj",w,h:-x})});return {id,t:"Requested a contractor for "+n+"'s overload",req:q.id}}},
  {id:"agent",t:ag?"Offload "+f1(offH)+" hours of requests and routine work to "+ag.d.name:"Offload routine work to an AI agent",h:offH,cost:Math.round(offH*.5*8),ok:!!ag&&offH>.5,risk:"The agent works inside its autonomy tier and "+(ag?E(acctOf(ag.d.name)||"its owner"):"its owner")+" stays accountable. Covers requests and routine work only.",apply:()=>{const id="FX"+FXN++;ow.forEach(([w,h])=>{const rq=m.T.req[w],bu=m.T.bau[w],x=Math.min(h,(rq+bu)*.35);if(x>0.01){const a=Math.min(x,rq*.35),b=x-a;if(a>0)CAP.ov.push({fx:id,owner:n,type:"req",w,h:-a});if(b>0)CAP.ov.push({fx:id,owner:n,type:"bau",w,h:-b});CAP.ov.push({fx:id,owner:ag.d.name,type:"req",w,h:x*.5})}});return {id,t:"Offloaded routine work from "+n+" to "+ag.d.name}}},
  {id:"defer",t:"Defer "+f1(dh)+" hours of project work by "+Math.max(2,Math.ceil(ow.length/2))+" weeks",h:dh,cost:0,ok:dh>0,risk:"Project dates move. Check the critical path before agreeing.",apply:()=>{const id="FX"+FXN++;const sh=Math.max(2,Math.ceil(ow.length/2));ow.forEach(([w,h])=>{const x=Math.min(h,m.T.proj[w]);if(x>0){CAP.ov.push({fx:id,owner:n,type:"proj",w,h:-x});const t=Math.min(NWK-1,wB+1+(w%sh));CAP.ov.push({fx:id,owner:n,type:"proj",w:t,h:x})}});return {id,t:"Deferred project work for "+n}}}];
 return {n,ow,tot,opts,peak:Math.max(...ow.map(x=>x[1]))}}
function levelDrawer(n){const L=levelOpts(n);if(!L){toast(n+" is not over capacity in the next 26 weeks.","info");return}const r=who(n);
 openDrawer(`<div class="eyebrow">Leveling</div><div class="row">${avatar(r,{size:52})}<div><h2 style="font-size:28px;margin:0">${E(n)}</h2>${kindPill(r.kind)}</div></div><p class="story" data-role="story">${L.ow.length} weeks over 100% in the next 26, ${f1(L.tot)} hours above capacity in total, worst week ${f1(L.peak)} hours over. The Resource Agent ranked four fixes. You decide; each one can be undone.</p>
 ${L.opts.map((o,i)=>`<div class="pp2-fix${o.ok?"":" off"}"><div class="row sp"><b>${i+1}. ${E(o.t)}</b><span class="pill ${o.ok?"info":"mute"}">${o.ok?f1(Math.min(o.h,L.tot))+" h":"Not available"}</span></div><p class="small muted">${o.risk}</p>${o.cost?`<p class="small">Estimated cost $${fmt(o.cost)}</p>`:""}<button class="btn ${i===0&&o.ok?"primary":""}" data-pp2-act="fix" data-a="${E(n)}|${o.id}"${o.ok?"":" disabled"}>Apply this</button></div>`).join("")}
 ${aiChip({model:"Resource Agent",conf:.82,title:"How the fixes were found",src:["Team members' available hours for the same weeks","Agent load and autonomy tiers","Contractor rate card","Project task hours"],guards:["Proposes only. You decide.","Nothing moves without your Apply"]})}`)}
function applyFix(n,id){const L=levelOpts(n);if(!L)return;const o=L.opts.find(x=>x.id===id);if(!o||!o.ok)return;const before=Math.max(...PM(n).util.slice(0,26));const res=o.apply();bumpMv();const after=Math.max(...PM(n).util.slice(0,26));CAP.applied.unshift({id:res.id,n,t:res.t,at:"Oct 7",before,after,req:res.req});audit("leveling applied",res.t);toast(res.t+". Peak load "+pc(before)+" to "+pc(after)+".","good");closeDrawer();render()}
function undoFix(id){CAP.ov=CAP.ov.filter(o=>o.fx!==id);CAP.reqs=CAP.reqs.filter(q=>q.fx!==id);CAP.applied=CAP.applied.filter(a=>a.id!==id);bumpMv();audit("leveling undone",id);toast("Undone","good");render()}
function overTab(){const names=scopeNames().filter(n=>who(n).kind!=="msp");const rows=[];names.forEach(n=>{const ow=overWeeks(n,0,25);if(ow.length)rows.push({id:n,name:n,team:who(n).team||"",kind:KINDS[who(n).kind],weeks:ow.length,peak:Math.round(Math.max(...ow.map(x=>x[1]))),hrs:Math.round(ow.reduce((a,x)=>a+x[1],0)),first:wkLab(ow[0][0])})});rows.sort((a,b)=>b.hrs-a.hrs);
 const tmo={};rows.forEach(r=>tmo[r.team]=(tmo[r.team]||0)+1);const topT=Object.entries(tmo).sort((a,b)=>b[1]-a[1])[0];
 return scopeBar()+`<p class="story" data-role="story"><b>${rows.length}</b> ${rows.length===1?"person is":"people are"} over capacity in the next 26 weeks${topT?`, most of them in <b>${E(topT[0])}</b> (${topT[1]})`:""}. For each person the Resource Agent offers four fixes: move work to a teammate, add a contractor, offload routine work to an AI agent, or defer project work. Nothing changes until you apply one.</p>
 ${CAP.applied.length?card("Applied fixes","Each fix can be undone.",`<ul class="pp2-fixes">${CAP.applied.map(a=>`<li><span><b>${E(a.t)}</b> <span class="muted small">peak ${pc(a.before)} to ${pc(a.after)} · ${a.at}</span></span><button class="btn quiet" data-pp2-act="unfix" data-a="${a.id}">Undo</button></li>`).join("")}</ul>`):""}
 ${card("People over capacity","Sorted by hours above capacity. Select a person to see the fixes.",btHTML({id:"pp2_ovl",cols:[{k:"name",label:"Person",fmt:r=>pchip(r.name)},{k:"team",label:"Team"},{k:"kind",label:"Kind"},{k:"weeks",label:"Weeks over"},{k:"peak",label:"Worst week (h over)"},{k:"hrs",label:"Total hours over"},{k:"first",label:"First week"},{k:"fix",label:"",fmt:r=>`<button class="btn quiet" data-pp2-act="level" data-a="${E(r.name)}">Fixes</button>`}],rows:()=>rows,key:"id",h:440,rowH:44,facets:["team","kind"],groupBy:["team"],exportName:"over-capacity",open:id=>levelDrawer(id)}))}`}
