function capDash(){const t0=performance.now();syncCap();const names=scopeNames();const A=scopeAgg(),ms=performance.now()-t0;const o=ovStats(names,0,11);const gap=gapFTE(0,11);const pend=CAP.reqs.filter(q=>q.status==="Submitted"||q.status==="Resource manager");
 const teams=teamList().map(t=>{const a=gagg("team",t);const L=groupNames("team",t);const ov=ovStats(L,0,11);return {id:t,team:t,n:L.length,u:Math.round(avgU(a,0,11)*100),peak:Math.round(Math.max(...Array.from(a.util.slice(0,12)).map(x=>Math.min(x,3)))*100),over:ov.people,gap:+(Math.max(0,mean(Array.from(a.tot.slice(0,12)))-mean(Array.from(a.cap.slice(0,12))))/40).toFixed(1),fut:Math.round(avgU(a,12,25)*100)}}).filter(r=>r.n);
 const pk=(()=>{let b=0;for(let w=0;w<26;w++)if(A.util[w]>A.util[b])b=w;return b})();
 const story=`Every kind of work is turned into hours per person per week: projects, incidents, requests, changes, on-call, operational work, meetings, training and leave. For <b>${fmt(names.length)} workers</b> over ${NWK} weeks, load over the next 12 weeks is <b>${pc(avgU(A,0,11))}</b>. <b>${o.people}</b> ${o.people===1?"person is":"people are"} over 100% in at least one week (${o.over} weeks in total across them). Demand with no named person is <b>${f1(gap)} FTE</b>. The tightest week is ${wkLab(pk)} at ${pc(A.util[pk])}. ${pend.length} resource ${pend.length===1?"request is":"requests are"} waiting.`;
 const lab=WK.map(w=>w.lab);const mx=Math.max(1,...Array.from(A.tot),...Array.from(A.cap))*1.08;
 return scopeBar()+`<p class="story" data-role="story">${story}</p>
 <div class="statrow">${stat("Load, next 12 weeks",pc(avgU(A,0,11)),"target band 70% to 88%",avgU(A,0,11)>1?"crit":"")}${stat("People over capacity",String(o.people),fmt(o.over)+" person-weeks",o.people?"warn":"")}${stat("Unstaffed demand",f1(gap)+" FTE","no named person")}${stat("Resource requests waiting",String(pend.length),"answered in 5 days")}</div>
 ${card("Capacity against demand, all 52 weeks","Demand is every work type added together. The dashed line is available hours after leave and holidays.",lineChart(lab,[{vals:Array.from(A.tot),color:"var(--p4)",area:true},{vals:Array.from(A.cap),color:"var(--good-f)",dash:true}],{max:mx,every:4,fmt:v=>fmt(v/1000*10)/10+"k",w:900,h:280})+legend([["Demand (all work types)","--p4"],["Available hours","--good-f"]]))}
 ${card("Teams","Average load over the next 12 weeks and the 13 weeks after. Select a team to see its people.",btHTML({id:"pp2_cteams",cols:[{k:"team",label:"Team",fmt:r=>`<button class="pp2-lnk" data-pp2-act="rgrp" data-a="team|${E(r.team)}">${E(r.team)}</button>`},{k:"n",label:"Workers"},{k:"u",label:"Load, next 12 weeks",fmt:r=>`<span class="pill ${uCls(r.u/100)}">${r.u}%</span>`},{k:"fut",label:"Weeks 13 to 26",fmt:r=>r.fut+"%"},{k:"peak",label:"Peak week",fmt:r=>r.peak+"%"},{k:"over",label:"People over 100%"},{k:"gap",label:"Shortfall (FTE)"}],rows:()=>teams,key:"id",h:300,rowH:44,exportName:"team-capacity"}))}
 ${card("Everyone","Each person's load against the target band for their role family. Select a row for everything on their plate.",btHTML({id:"pp2_cppl",cols:[{k:"name",label:"Person",fmt:r=>pchip(r.name)},{k:"kind",label:"Kind"},{k:"team",label:"Team"},{k:"fam",label:"Role family"},{k:"u",label:"Load, next 12 weeks",fmt:r=>`<span class="pill ${uCls(r.u/100)}">${r.u}%</span>`},{k:"band",label:"Target band"},{k:"over",label:"Weeks over 100%"},{k:"room",label:"Room (h a week)"}],rows:()=>names.filter(n=>who(n).kind!=="msp").map(n=>{const m=PM(n),r=m.r,tg=tgtOf(r),u=avgU({cap:m.cap,tot:m.tot},0,11);let room=1e9;for(let w=0;w<8;w++)if(m.cap[w]>.5)room=Math.min(room,Math.max(0,tg[1]*m.cap[w]-m.tot[w]));return {id:n,name:n,kind:KINDS[r.kind],team:r.team||"",fam:rfam(r),u:Math.round(u*100),band:Math.round(tg[0]*100)+"% to "+Math.round(tg[1]*100)+"%",over:Array.from(m.util.slice(0,26)).filter((x,w)=>x>1.0001&&m.cap[w]>.5).length,room:room===1e9?0:Math.round(room)}}),key:"id",h:460,rowH:44,facets:["team","kind","fam"],groupBy:["team","fam","kind"],exportName:"people-capacity",open:id=>{CAP.person=id;st.tab.ppl_cap=3;go("ppl_cap")}}))}
 ${card("Scale test","The model is rebuilt from the sources on demand, so it holds for hundreds or thousands of people.",`<p class="small">${fmt(DIR.length)} workers × ${NWK} weeks × ${WT.length} work types = <b>${fmt(DIR.length*NWK*WT.length)}</b> cells. ${CAP.scaleMs!=null?`Last full rebuild took <b>${Math.round(CAP.scaleMs)} ms</b>.`:"Run the test to time a full rebuild."} Switch on Enterprise mode (about 400 people) in the settings menu to try it.</p><button class="btn" data-pp2-act="scaletest">Rebuild all and time it</button>`)}`}
function workTab(){const A=scopeAgg();const mons=MONTHS.map(m=>{const n=m.w1-m.w0+1;const o={lab:m.lab,cap:0};WTK.forEach(k=>{let s=0;for(let w=m.w0;w<=m.w1;w++)s+=A.T[k][w];o[k]=s/n});for(let w=m.w0;w<=m.w1;w++)o.cap+=A.cap[w];o.cap/=n;return o});const mx=Math.max(1,...mons.map(o=>Math.max(o.cap,WTK.reduce((a,k)=>a+o[k],0))))*1.05;
 const tot=WTK.reduce((a,k)=>a+mean(Array.from(A.T[k].slice(0,12))),0)||1;
 const srcN={proj:()=>{try{return PPMX.tasksOf({}).filter(t=>!t.ms&&t.pct<100).length}catch(e){return TASKS.length}},inc:()=>{try{return S.itsm.inc.filter(i=>!/Resolved|Closed/.test(i.st)).length}catch(e){return 0}},req:()=>(window.REQREG||[]).filter(r=>!r.done).length,chg:()=>{try{return S.itsm.chg.filter(c=>!c.hist).length+(window.RELX?RELX.releases.length:0)}catch(e){return 0}},oncall:()=>{try{return OCX.allPto().length}catch(e){return 0}},bau:()=>DIR.length,mtg:()=>MEETINGS.length,train:()=>DIR.length};
 const from={proj:"Schedule engine (project plans)",inc:"Incident and problem queues",req:"Service catalog requests",chg:"Change calendar and release trains",oncall:"On-call rota",bau:"Role-family operating model",mtg:"Calendar",train:"Learning plans"};
 return scopeBar()+`<p class="story" data-role="story">This is how the model scales across every kind of work: each work type is an adapter that turns its records into hours per person per week, and everything downstream (heatmaps, leveling, scenarios, forecasts) reads the same hours. A new work type is one adapter. Today there are ${WT.length}, plus leave and holidays, which reduce capacity instead of adding demand.</p>
 ${card("Demand by work type, by month","Average weekly hours across the selected workers. The line is available hours.",`<div class="pp2-mobars" role="img" aria-label="Monthly demand by work type">${mons.map(o=>`<div class="pp2-mb"><span class="pp2-mobs">${WT.map(([k,l,c])=>o[k]>0?`<i style="height:${o[k]/mx*100}%;background:var(${c})" title="${l}: ${fmt(o[k])} h"></i>`:"").join("")}</span><s style="bottom:${o.cap/mx*100}%"></s><small>${o.lab}</small></div>`).join("")}</div>${typeLeg()}`)}
 ${card("Where each work type comes from","Adapters, their sources and how many records feed the model right now.",`<div class="tscroll"><table><thead><tr><th>Work type</th><th>Source</th><th>Records</th><th>Hours a week, next 12 weeks</th><th>Share</th><th>Fills the gap with</th></tr></thead><tbody>${WT.map(([k,l,c])=>{const h=mean(Array.from(A.T[k].slice(0,12)));return `<tr><td><i class="pp2-sw" style="background:var(${c})"></i>${l}</td><td>${from[k]}</td><td class="num">${fmt(srcN[k]())}</td><td class="num">${fmt(h)}</td><td class="num">${Math.round(h/tot*100)}%</td><td class="small">${{proj:"Contractor or defer",inc:"Agent triage and on-call swaps",req:"AI agent fulfillment",chg:"Release train scheduling",oncall:"Rota swaps",bau:"Automation and agents",mtg:"Fewer, shorter meetings",train:"Defer outside peaks"}[k]}</td></tr>`}).join("")}</tbody></table></div><p class="muted small">Leave and holidays come from approved time off and the company calendar. Contractors drop to zero after their end date. Providers count contracted hours, not people.</p>`)}`}
