function scenCalc(sc,A){const tms=selSet("pp2ct",teamList());const add=new Float32Array(NWK),capAdd=new Float32Array(NWK),cut=new Float32Array(NWK);
 for(let w=0;w<NWK;w++){if(w>=sc.from&&w<sc.from+sc.weeks)capAdd[w]=sc.ctr*sc.ctrH;cut[w]=A.T.bau[w]*sc.bau/100+A.T.req[w]*sc.agent/100*.5}
 let cost=sc.ctr*sc.ctrH*Math.min(sc.weeks,NWK-sc.from)*rateAvg();const picked=[];(sc.proj||[]).forEach(id=>{const d=DEMAND.find(x=>x.id===id);if(!d)return;picked.push(d);cost+=d.cost*1000;const w0=Math.round(d.m0*4.35),w1=Math.min(NWK-1,Math.round((d.m0+d.mo)*4.35));(d.res||[]).forEach(([t,f])=>{if(tms.includes(t))for(let w=w0;w<=w1;w++)add[w]+=f*40})});
 const u0=[],u1=[];let o0=0,o1=0;for(let w=0;w<NWK;w++){u0.push(A.cap[w]>.5?A.tot[w]/A.cap[w]:0);const c=A.cap[w]+capAdd[w],d=A.tot[w]+add[w]-cut[w];u1.push(c>.5?d/c:0);if(u0[w]>1.0001)o0++;if(u1[w]>1.0001)o1++}
 return {u0,u1,o0,o1,cost,picked,peak0:Math.max(...u0),peak1:Math.max(...u1),avg0:mean(u0.slice(0,26)),avg1:mean(u1.slice(0,26)),hoursCut:cut.reduce((a,b)=>a+b,0)}}
function scenTab(){const A=scopeAgg(),sc=CAP.scen,R=scenCalc(sc,A);const lab=WK.map(w=>w.lab);
 return scopeBar()+`<p class="story" data-role="story">Try a change on paper before committing to it. Your current assumptions: <b>${sc.ctr} contractors</b> at ${sc.ctrH} hours a week for ${sc.weeks} weeks from ${wkLab(sc.from)}${sc.proj.length?`, approve <b>${sc.proj.map(id=>E((DEMAND.find(d=>d.id===id)||{}).n||id)).join(" and ")}</b>`:""}${sc.bau?`, cut operational work by <b>${sc.bau}%</b>`:""}${sc.agent?`, move <b>${sc.agent}%</b> of requests to agents`:""}. Over the next 26 weeks that moves average load from <b>${pc(R.avg0)}</b> to <b>${pc(R.avg1)}</b> and weeks above 100% from ${R.o0} to ${R.o1} of ${NWK}.${R.avg0===R.avg1&&R.o0===R.o1?" <b>No change yet.</b> Add contractors, approve a project from Demand, or move requests to agents to see an effect.":""}</p>
 <div class="row" style="margin-bottom:12px"><button class="btn primary" data-pp2-act="scenedit">Change assumptions</button><button class="btn" data-pp2-act="scensave">Save scenario</button><button class="btn" data-pp2-act="scencommit"${sc.ctr||sc.proj.length?"":" disabled"}>Turn into resource requests</button></div>
 <div class="statrow">${stat("Peak load",pc(R.peak0)+" to "+pc(R.peak1),"all 52 weeks",R.peak1>1?"crit":"")}${stat("Weeks above 100%",R.o0+" to "+R.o1,"of "+NWK)}${stat("Added cost","$"+fmt(R.cost/1000)+"k","contractors and approved projects")}${stat("Hours freed a week",fmt(R.hoursCut/NWK),"operational cut and agent offload")}</div>
 ${card("Load before and after","Solid is today. Dashed is with your assumptions.",lineChart(lab,[{vals:R.u0.map(v=>Math.min(v*100,160)),color:"var(--p4)"},{vals:R.u1.map(v=>Math.min(v*100,160)),color:"var(--good-f)",dash:true},{vals:lab.map(()=>100),color:"var(--bad-f)",dash:true,w:1.5}],{max:160,every:4,fmt:v=>Math.round(v)+"%",w:900,h:260})+legend([["Today","--p4"],["With assumptions","--good-f"],["100% line","--bad-f"]]))}
 ${R.picked.length?card("Projects in this scenario","Each project adds its resource ask to the teams in scope.",`<div class="tscroll"><table><thead><tr><th>Project</th><th>Cost</th><th>Needs</th><th>Starts</th></tr></thead><tbody>${R.picked.map(d=>`<tr><td>${E(d.n)}</td><td class="num">$${fmt(d.cost)}k</td><td>${d.res.map(x=>E(x[0])+" "+x[1]+" FTE").join(", ")}</td><td>${wkLab(Math.round(d.m0*4.35))}</td></tr>`).join("")}</tbody></table></div>`):""}
 ${CAP.saved.length?card("Saved scenarios","Compare what you tried.",`<div class="tscroll"><table><thead><tr><th>Name</th><th>Peak</th><th>Weeks above 100%</th><th>Cost</th><th></th></tr></thead><tbody>${CAP.saved.map((s,i)=>`<tr><td>${E(s.n)}</td><td class="num">${pc(s.peak)}</td><td class="num">${s.over}</td><td class="num">$${fmt(s.cost/1000)}k</td><td><button class="btn quiet" data-pp2-act="scenload" data-a="${i}">Load</button></td></tr>`).join("")}</tbody></table></div>`):""}`}
function scenForm(){const sc=CAP.scen;openForm({id:"pp2_scen",title:"Scenario assumptions",story:"Change anything and the result updates below. Nothing is committed until you turn the scenario into requests.",submit:"Use these assumptions",fields:[{k:"ctr",label:"Contractors to add",type:"number",min:0,max:40},{k:"ctrH",label:"Hours a week each",type:"number",min:8,max:40},{k:"from",label:"Starting week",type:"select",opts:WK.slice(0,40).map(w=>[String(w.i),"Week of "+w.lab])},{k:"weeks",label:"For how many weeks",type:"number",min:2,max:52},{k:"proj",label:"Approve these projects",type:"multi",opts:DEMAND.filter(d=>d.st<=3).map(d=>[d.id,d.n+" ($"+d.cost+"k)"])},{k:"bau",label:"Cut operational work by",type:"range",min:0,max:30,unit:"%"},{k:"agent",label:"Move this share of requests to agents",type:"range",min:0,max:60,unit:"%"}],defaults:{ctr:sc.ctr,ctrH:sc.ctrH,from:String(sc.from),weeks:sc.weeks,proj:sc.proj,bau:sc.bau,agent:sc.agent},
 live:v=>{const R=scenCalc({ctr:+v.ctr||0,ctrH:+v.ctrH||0,from:+v.from||0,weeks:+v.weeks||1,proj:v.proj||[],bau:+v.bau||0,agent:+v.agent||0},scopeAgg());return `<div class="pp2-live"><b>Result</b> Average load, next 26 weeks: ${pc(R.avg0)} to <b>${pc(R.avg1)}</b>. Weeks above 100%: ${R.o0} to <b>${R.o1}</b>. Added cost $${fmt(R.cost/1000)}k.</div>`},
 onSubmit:v=>{CAP.scen={ctr:+v.ctr||0,ctrH:+v.ctrH||0,from:+v.from||0,weeks:+v.weeks||1,proj:v.proj||[],bau:+v.bau||0,agent:+v.agent||0};audit("changed capacity scenario","");return {toast:"Scenario updated"}}})}
/* ---- forecast ---- */
function forecastTab(){const A=scopeAgg();const mons=MONTHS.map(m=>{let c=0,d=0,n=0;for(let w=m.w0;w<=m.w1;w++){c+=A.cap[w];d+=A.tot[w];n++}c/=n;d/=n;return {lab:m.lab,cap:c,dem:d,gap:(d-c)/40,n}});const gapM=mons.filter(m=>m.gap>.5);const mxG=Math.max(0,...mons.map(m=>m.gap));const avgGap=gapM.length?mean(gapM.map(m=>m.gap)):0;const peak=mons.reduce((a,m)=>m.gap>a.gap?m:a,mons[0]);
 const rate=rateAvg(),loaded=loadedAvg();const weeksG=gapM.length*4.35;const hireC=avgGap*loaded*Math.max(1,gapM.length)/12*1.0,ctrC=avgGap*40*weeksG*rate,mspC=Math.max(avgGap*40*weeksG*88,3*160*88);const reqShare=(()=>{let r=0,t=0;for(let w=0;w<26;w++){r+=A.T.req[w]+A.T.bau[w]*.5;t+=A.tot[w]}return t?r/t:0})();const aiC=gapM.length?Math.round(avgGap*40*weeksG*reqShare*.35):0;
 const rec=gapM.length===0?"No gap to fill. Hold the current team.":gapM.length>=9?"The shortfall lasts most of the year, so hiring is cheaper than renting. Open a role now: with a 10-week lead time the first months need a contractor bridge.":gapM.length<=5?"The shortfall is short-lived. A contractor or provider is cheaper than a hire you would not need after "+gapM[gapM.length-1].lab+".":"A mix fits: hire for the baseline gap and use contractors for the peak.";
 const mx=Math.max(1,...mons.map(m=>Math.max(m.cap,m.dem)))*1.1;
 return scopeBar()+`<p class="story" data-role="story">${gapM.length?`Demand is above capacity in <b>${gapM.length} of 12 months</b>, worst in <b>${peak.lab}</b> at ${f1(peak.gap)} FTE short (average ${f1(avgGap)} FTE in the months that are short). ${rec}`:"Capacity covers demand in every month. "+rec}</p>
 ${card("Demand against capacity, by month","Average weekly hours. Bars over the line are months with a shortfall.",`<div class="pp2-mobars" role="img" aria-label="Monthly demand against capacity">${mons.map(m=>`<div class="pp2-mob ${m.gap>.5?"short":""}"><span class="pp2-mobs"><i style="height:${m.dem/mx*100}%;background:var(${m.gap>.5?"--bad-f":"--p4"})" title="Demand ${fmt(m.dem)} h"></i></span><s style="bottom:${m.cap/mx*100}%"></s><small>${m.lab}</small><em>${m.gap>.5?f1(m.gap)+" FTE":""}</em></div>`).join("")}</div>${legend([["Demand","--p4"],["Demand above capacity","--bad-f"],["Available hours","--good-f"]])}`)}
 ${card("Hire or buy","Cost to cover the shortfall over the year for each option. Estimates, based on today's rate card and open roles.",`<div class="tscroll"><table><thead><tr><th>Option</th><th>Lead time</th><th>Cost for the gap</th><th>Good when</th><th>Watch for</th></tr></thead><tbody>
 <tr><td><b>Hire employees</b></td><td>About 10 weeks</td><td class="num">$${fmt(hireC/1000)}k</td><td class="small">The gap lasts 9 months or more</td><td class="small">Half productivity for the first 3 months</td></tr>
 <tr><td><b>Contractors</b></td><td>About 2 weeks</td><td class="num">$${fmt(ctrC/1000)}k</td><td class="small">Short or uncertain demand</td><td class="small">$${rate} an hour average; knowledge leaves with them</td></tr>
 <tr><td><b>Managed service provider</b></td><td>About 4 weeks</td><td class="num">$${fmt(mspC/1000)}k</td><td class="small">Steady, well-defined run work</td><td class="small">Minimum monthly commitment; credits for missed levels</td></tr>
 <tr><td><b>AI agents</b></td><td>Days</td><td class="num">$${fmt(aiC*8/1000)}k</td><td class="small">Requests and routine work (${Math.round(reqShare*100)}% of demand)</td><td class="small">Covers up to ${fmt(aiC)} hours; needs an accountable human</td></tr></tbody></table></div><div class="row" style="margin-top:12px"><button class="btn primary" data-pp2-act="newreq" data-a="">Request resources</button><button class="btn" data-pp2-act="scenedit">Try it as a scenario</button></div>`)}
 ${card("Open roles","Roles already being filled count against the gap once started.",st.vac.filter(v=>v.status!=="Filled").length?`<div class="tscroll"><table><thead><tr><th>Role</th><th>Team</th><th>Status</th><th>Open since</th><th>Skills</th></tr></thead><tbody>${st.vac.filter(v=>v.status!=="Filled").map(v=>`<tr><td>${E(v.title)}</td><td>${E(v.team)}</td><td><span class="pill info">${E(v.status)}</span></td><td>${E(v.opened)}</td><td class="small">${E((v.skills||[]).join(", "))}</td></tr>`).join("")}</tbody></table></div>`:'<p class="muted">No open roles.</p>')}`}
/* ---- bench and requests ---- */
function candidates(q){const w0=clamp(wkOfIso(q.from),0,NWK-1),w1=clamp(wkOfIso(q.to),w0,NWK-1);const L=DIR.filter(d=>(q.kind==="any"||d.kind===q.kind)&&d.team&&!(d.kind==="contractor"&&d.end&&wkOfIso(d.end)<w1)).map(d=>{const m=PM(d.name),tg=tgtOf(d);let room=0,n=0;for(let w=w0;w<=Math.min(w1,w0+11);w++){room+=Math.max(0,tg[1]*m.cap[w]-m.tot[w]);n++}room/=Math.max(1,n);const ov=(q.skills||[]).filter(s=>(d.skills||[]).some(x=>x.toLowerCase()===s.toLowerCase())).length;return {d,room,ov,score:ov*20+Math.min(room,q.fte*40)+(d.team===q.team?5:0)}}).filter(x=>x.room>=q.fte*40*.4||q.kind==="ai").sort((a,b)=>b.score-a.score);return L.slice(0,5)}
function rqCard(q){const c=q.status==="Filled"?[]:candidates(q).slice(0,2);return `<div class="pp2-wi" data-dnd-id="${q.id}"><span class="grip" aria-hidden="true"></span><div><button class="pp2-lnk" data-pp2-act="rq" data-a="${q.id}"><b>${E(q.title)}</b></button><div class="small muted">${E(q.team)} · ${RQKIND[q.kind]} · ${q.fte} FTE · ${DT(q.from)} to ${DT(q.to)}</div>${c.length?`<div class="small">Best matches: ${c.map(x=>E(x.d.name)).join(", ")}</div>`:q.filledBy?`<div class="small">Filled by ${pchip(q.filledBy)}</div>`:""}</div></div>`}
function benchTab(){const names=DIR.filter(d=>d.kind!=="msp"&&d.team).map(d=>d.name);const bench=names.map(n=>{const m=PM(n),u=avgU({cap:m.cap,tot:m.tot},0,7);let room=0;for(let w=0;w<8;w++)room+=Math.max(0,tgtOf(m.r)[1]*m.cap[w]-m.tot[w]);return {id:n,name:n,kind:KINDS[m.r.kind],team:m.r.team||"",u:Math.round(u*100),room:Math.round(room/8),skills:(m.r.skills||[]).slice(0,3).join(", ")}}).filter(r=>r.u<65&&r.room>=8).sort((a,b)=>b.room-a.room);
 const cols=RQST.map(s=>[s,s]);const open=CAP.reqs.filter(q=>q.status!=="Filled");const fte=open.reduce((a,q)=>a+q.fte,0);
 return `<p class="story" data-role="story">${open.length} open resource requests ask for <b>${f1(fte)} FTE</b>. ${bench.length} people have room of 8 hours a week or more over the next 8 weeks. Drag a request between columns as it moves through the resource manager. The agent lists the best matches from all four kinds of worker, checked against skills and available hours.</p>
 <div class="row" style="margin-bottom:12px"><button class="btn primary" data-pp2-act="newreq" data-a="">New resource request</button></div>
 <div class="pp2-kanban pp2-k4">${cols.map(([k,l])=>{const L=CAP.reqs.filter(q=>q.status===k);return `<div class="pp2-kc"><h4>${l} <span class="muted">${L.length}</span></h4><div class="pp2-kl" data-dnd="${k}" data-dnd-scope="pp2rq">${L.map(rqCard).join("")}</div></div>`}).join("")}</div>
 ${legend([["Submitted","--faint"],["With the resource manager","--p4"],["Approved","--good-f"],["Filled","--s3"]])}
 ${card("Bench","People and providers with room in the next 8 weeks.",btHTML({id:"pp2_bench",cols:[{k:"name",label:"Person",fmt:r=>pchip(r.name)},{k:"kind",label:"Kind"},{k:"team",label:"Team"},{k:"u",label:"Load",fmt:r=>`<span class="pill ${uCls(r.u/100)}">${r.u}%</span>`},{k:"room",label:"Room (h a week)"},{k:"skills",label:"Skills"}],rows:()=>bench,key:"id",h:380,rowH:44,facets:["team","kind"],groupBy:["team","kind"],exportName:"bench",open:id=>{CAP.person=id;st.tab.ppl_cap=3;go("ppl_cap")}}))}`}
function rqDrawer(id){const q=CAP.reqs.find(x=>x.id===id);if(!q)return;const c=candidates(q);openDrawer(`<div class="eyebrow">Resource request ${q.id}</div><h2 style="font-size:26px;margin:4px 0 8px">${E(q.title)}</h2><p class="story" data-role="story">${E(q.by)} asks for <b>${q.fte} FTE</b> from ${DT(q.from)} to ${DT(q.to)} for ${E(q.team)}. ${E(q.why)}</p><dl class="kv"><dt>Kind</dt><dd>${RQKIND[q.kind]}</dd><dt>Role family</dt><dd>${E(q.role||"")}</dd><dt>Skills</dt><dd>${E((q.skills||[]).join(", ")||"Any")}</dd><dt>Status</dt><dd><span class="pill info">${q.status}</span></dd></dl>
 ${q.status!=="Filled"?`<div class="eyebrow" style="margin-top:12px">Best matches</div>${c.length?lrHTML({id:"pp2rm"+q.id,groups:[{key:"a",label:"Skills and room",rows:c.map(x=>({id:x.d.name,t:x.d.name,sub:KINDS[x.d.kind]+" · "+x.ov+" skill match"+(x.ov===1?"":"es")+" · "+Math.round(x.room)+" h a week free",tag:x.d.team,st:"info",go:()=>{CAP.person=x.d.name;closeDrawer();st.tab.ppl_cap=3;go("ppl_cap")}}))}],limit:5}):'<p class="muted small">No one has room. Consider a contractor.</p>'}<div class="row" style="margin-top:12px">${q.status!=="Approved"?`<button class="btn primary" data-pp2-act="rqmove" data-a="${q.id}|Approved">Approve</button>`:""}<button class="btn" data-pp2-act="rqfill" data-a="${q.id}">Mark filled</button></div>`:`<p class="small">Filled by ${q.filledBy?pchip(q.filledBy):"a named person"}.</p>`}`)}
function fillForm(id){const q=CAP.reqs.find(x=>x.id===id);if(!q)return;const c=candidates(q);openForm({id:"pp2_fill",title:"Who fills "+q.title+"?",story:"Pick the person or worker who takes this on. Their hours start counting from the first week.",submit:"Mark filled",fields:[{k:"p",label:"Person",type:"select",req:true,opts:c.map(x=>[x.d.name,x.d.name+" · "+KINDS[x.d.kind]]).concat(DIR.filter(d=>d.team===q.team).slice(0,30).map(d=>[d.name,d.name+" · "+d.team])).filter((o,i,a)=>a.findIndex(z=>z[0]===o[0])===i)}],defaults:{p:c[0]&&c[0].d.name},onSubmit:v=>{q.status="Filled";q.fulfilled=true;q.filledBy=v.p;const w0=clamp(wkOfIso(q.from),0,NWK-1),w1=clamp(wkOfIso(q.to),w0,NWK-1);for(let w=w0;w<=w1;w++)CAP.ov.push({fx:"FL"+q.id,owner:v.p,type:"proj",w,h:q.fte*40});decide(q);bumpMv();audit("filled resource request",q.title+" with "+v.p);return {toast:q.title+" filled by "+v.p}}})}
function decide(q){q.decided=true;q.days=Math.max(1,Math.round((Date.parse("2026-10-07")-Date.parse(q.at))/DAY));}
DND.on("pp2rq",(id,from,to)=>{const q=CAP.reqs.find(x=>x.id===id);if(!q||q.status===to)return;if(to==="Filled"){render();fillForm(id);return}q.status=to;if(to==="Approved")decide(q);bumpMv();audit("moved resource request",q.title+" to "+to);toast(q.title+" is now "+to.toLowerCase(),"good");render()});
function newReq(pre){const tms=teamList();openForm({id:"pp2_nreq",title:"New resource request",story:"Describe the need. A request creates unstaffed demand in the plan until it is filled, so the heatmaps show the pressure right away.",submit:"Submit request",fields:[{k:"title",label:"What is needed",type:"text",req:true,ph:"Two engineers for the portal build",ai:{label:"Write it",fn:v=>"Extra "+(v.role||"capacity")+" for "+(v.team||"the team")}},{k:"team",label:"Team",type:"select",req:true,opts:tms},{k:"kind",label:"Kind of worker",type:"chips",opts:Object.entries(RQKIND)},{k:"role",label:"Role family",type:"select",opts:ROLEFAMS},{k:"skills",label:"Skills",type:"multi",opts:[...new Set(DIR.flatMap(d=>d.skills||[]))].slice(0,60).map(s=>[s,s])},{k:"fte",label:"Full-time equivalents",type:"range",min:.25,max:6,step:.25},{k:"from",label:"From",type:"date",req:true},{k:"to",label:"To",type:"date",req:true},{k:"why",label:"Why",type:"longtext",wide:true,req:true}],
 defaults:Object.assign({kind:"any",fte:1,from:"2026-11-02",to:"2027-01-29",team:tms[0],role:"Engineer or architect"},pre||{}),
 live:v=>{const q={kind:v.kind||"any",skills:v.skills||[],fte:+v.fte||1,from:v.from||"2026-11-02",to:v.to||"2027-01-29",team:v.team};const c=candidates(q);const wks=Math.max(1,(Date.parse(q.to)-Date.parse(q.from))/(7*DAY));return `<div class="pp2-live"><b>Estimate</b> ${f1(q.fte*40*wks)} hours. As contractors about $${fmt(q.fte*40*wks*rateAvg()/1000)}k. ${c.length?"Best match today: "+E(c[0].d.name)+" ("+Math.round(c[0].room)+" h a week free).":"No one in the directory has room, so this is likely a contractor or hire."}</div>`},
 onSubmit:v=>{const q={id:"RQ"+(CAP.reqs.length+1),title:v.title,team:v.team,role:v.role,kind:v.kind||"any",skills:v.skills||[],fte:+v.fte,from:v.from,to:v.to,status:"Submitted",by:"Omar Hamid",why:v.why,at:"2026-10-07"};CAP.reqs.unshift(q);bumpMv();audit("resource request",v.title);return {toast:"Request submitted. It is shown as unstaffed demand until filled."}}})}
/* ---- targets ---- */
function targetsTab(){const rows=ROLEFAMS.map(f=>{const L=DIR.filter(d=>rfam(d)===f&&d.kind!=="msp");const u=L.length?mean(L.map(d=>avgU({cap:PM(d.name).cap,tot:PM(d.name).tot},0,11))):0;const tg=CAP.tgt[f]||[.6,.85];return {f,n:L.length,u,lo:tg[0],hi:tg[1],st:u>tg[1]?"over":u<tg[0]?"under":"in"}});
 return `<p class="story" data-role="story">A target band says how busy each kind of role should be. A manager at 100% has no time to manage; a service desk analyst at 60% is waiting for work. ${rows.filter(r=>r.st==="over").length} role families are above their band and ${rows.filter(r=>r.st==="under").length} are below. Bands feed the "can they handle more?" answer and the overload checks.</p>
 ${card("Utilization targets by role family","Average load over the next 12 weeks against the band.",`<div class="tscroll"><table><thead><tr><th>Role family</th><th>People</th><th>Load, 12 weeks</th><th>Band</th><th></th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>${E(r.f)}</td><td class="num">${r.n}</td><td class="num">${pc(r.u)}</td><td class="num">${pc(r.lo)} to ${pc(r.hi)}</td><td><span class="pill ${r.st==="over"?"bad":r.st==="under"?"info":"good"}">${r.st==="over"?"Above band":r.st==="under"?"Below band":"In band"}</span></td><td><button class="btn quiet" data-pp2-act="tgt" data-a="${E(r.f)}">Edit</button></td></tr>`).join("")}</tbody></table></div>${legend([["In band","--good-f"],["Above band","--bad-f"],["Below band","--p6"]])}`)}`}
function tgtForm(f){const t=CAP.tgt[f];openForm({id:"pp2_tgt",title:"Target band for "+f,story:"Sets the load a healthy person in this role family should carry. Over the high end is flagged as risk; under the low end as spare capacity.",submit:"Save band",fields:[{k:"lo",label:"Low end",type:"range",min:30,max:90,unit:"%"},{k:"hi",label:"High end",type:"range",min:50,max:100,unit:"%"}],defaults:{lo:Math.round(t[0]*100),hi:Math.round(t[1]*100)},live:v=>+v.lo>=+v.hi?'<p class="small" style="color:var(--bad-f)">The low end must be below the high end.</p>':"",onSubmit:v=>{if(+v.lo>=+v.hi)return {toast:"The low end must be below the high end.",keep:true};CAP.tgt[f]=[+v.lo/100,+v.hi/100];TGT0[f]=CAP.tgt[f];audit("changed utilization target",f+": "+v.lo+"% to "+v.hi+"%");return {toast:"Band saved for "+f}}})}
/* ---- screen ---- */
function capScreen(){syncCap();const tab=tabIdx("ppl_cap",9);const panes=[capDash,heatTab,workTab,personTab,overTab,scenTab,forecastTab,benchTab,targetsTab];
 const A=agg(DIR.map(d=>d.name),"all:"+DIR.length+"|"+(st.mv||0)+"|"+(st.ver||0));const o=ovStats(DIR.map(d=>d.name),0,11);
 const story=`Planning covers <b>every kind of work</b>, not only projects: incidents, requests, changes, on-call, operational work, meetings, training and leave, for ${fmt(DIR.length)} employees, contractors, AI agents and providers across ${NWK} weeks. Load over the next 12 weeks is <b>${pc(avgU(A,0,11))}</b>, with <b>${o.people}</b> ${o.people===1?"person":"people"} over capacity. Pull any person to see everything on their plate and whether they can take more.`;
 return `<div class="screen">${hero("People and work","Resource planning",story,`<div class="row">${fchip("m_pp_util")}${fchip("m_pp_over")}${fchip("m_pp_gap")}<button class="btn primary" data-pp2-act="newreq" data-a="">Request resources</button><button class="btn" data-pp2-act="gocap" data-a="">Find a person</button>${stdChip("capplan")}${aiChip({model:"Resource Agent",conf:.82,title:"How capacity is computed",src:["Project plans and the schedule engine","Incidents, requests and changes","Calendar, leave and holidays","On-call rota","Contract end dates and provider hours"],guards:["Proposes only. You decide.","Does not see pay or performance ratings"]})}</div>`)}${lensNote()}${tabsBar("ppl_cap",["Dashboard","Heatmap","Work types","Person","Over capacity","Scenarios","Forecast","Bench and requests","Targets"])}<div class="pp2-pane">${panes[tab]()}</div>${procCard("ppl_cap")}</div>`}
REG("ppl_cap","Resource planning","people","M3 20V9M9 20V4M15 20v-8M21 20v-5M2 20h20",capScreen);
PROC.reg("ppl_cap",{title:"How resource planning works",std:["capplan","tt"],steps:[{n:"Collect demand",d:"Every work type reports hours per person per week: projects, incidents, requests, changes, on-call, operational work, meetings, training.",who:"auto",owner:"Resource Agent",sla:"Continuous",in:"Plans, queues, calendar",out:"Hours per person per week"},{n:"Subtract leave and holidays",d:"Approved time off and the company calendar reduce available hours. Contracts end on their end date.",who:"auto",owner:"Resource Agent",sla:"Continuous",in:"Leave, holidays, contracts",out:"Available hours"},{n:"Spot pressure",d:"Group and person load against the target band for the role family.",who:"agent",owner:"Resource Agent",sla:"Daily",in:"Demand and capacity",out:"Over and under capacity"},{n:"Propose fixes",d:"Move work, add a contractor, offload to an agent, or defer. Each with cost and risk.",who:"agent",owner:"Resource Agent",sla:"Same day",in:"Over capacity",out:"Ranked fixes"},{n:"Decide and request",d:"A manager applies a fix or raises a resource request. The resource manager approves.",who:"gate",owner:"Omar Hamid",sla:"5 working days",in:"Fix or request",out:"Decision"},{n:"Fill and re-plan",d:"The filled request adds hours to the named person and the plan updates.",who:"human",owner:"Priya Shah",sla:"Per request",in:"Approved request",out:"Updated plan"}]});
/* actions */
Object.assign(ACT,{heatdim(t){CAP.heat=t.dataset.a;CAP.pg.heat=0;render()},heatmore(){CAP.pg.heat=(CAP.pg.heat||0)+25;render()},rgrp(t){const [d,k]=t.dataset.a.split("|");groupDrawer(d,k,null)},rcell(t){const [d,k,w]=t.dataset.a.split("|");groupDrawer(d,k,+w)},level(t){levelDrawer(t.dataset.a)},fix(t){const [n,id]=t.dataset.a.split("|");applyFix(n,id)},unfix(t){undoFix(t.dataset.a)},
 capcsv(){const dim=CAP.heat;const rows=dim==="person"?scopeNames().map(n=>[n,PM(n)]):groupRows(dim).map(([k,l])=>[l,gagg(dim,k)]);csv("capacity-"+dim+".csv",[["Row"].concat(WK.map(w=>w.iso))].concat(rows.map(([l,a])=>[l].concat(WK.map((w,i)=>{const u=CAP.wt==="all"?(a.cap[i]>.5?a.tot[i]/a.cap[i]:null):cellVal(a,i,CAP.wt);return u==null?"":Math.round(u*100)})))));audit("exported capacity",dim);toast("Exported "+rows.length+" rows","good")},
 scaletest(){const t=performance.now();PMC.clear();TAC.clear();SRC=null;DIR.forEach(d=>PM(d.name));CAP.scaleMs=performance.now()-t;toast("Rebuilt "+fmt(DIR.length*NWK*WT.length)+" cells in "+Math.round(CAP.scaleMs)+" ms","good");render()},
 newreq(t){closeDrawer();newReq(t&&t.dataset&&t.dataset.a?{team:t.dataset.a,kind:t.dataset.b||"any"}:t&&t.dataset&&t.dataset.b?{kind:t.dataset.b}:null)},rq(t){rqDrawer(t.dataset.a)},rqmove(t){const [id,s]=t.dataset.a.split("|");const q=CAP.reqs.find(x=>x.id===id);if(q){q.status=s;if(s==="Approved")decide(q);bumpMv();audit("approved resource request",q.title);toast("Approved","good");closeDrawer();render()}},rqfill(t){closeDrawer();fillForm(t.dataset.a)},tgt(t){tgtForm(t.dataset.a)},
 scenedit(){scenForm()},scensave(){const R=scenCalc(CAP.scen,scopeAgg());CAP.saved.push({n:"Scenario "+(CAP.saved.length+1)+": "+CAP.scen.ctr+" contractors"+(CAP.scen.proj.length?" and "+CAP.scen.proj.length+" project(s)":""),peak:R.peak1,over:R.o1,cost:R.cost,sc:JSON.parse(JSON.stringify(CAP.scen))});toast("Scenario saved","good");render()},scenload(t){const s=CAP.saved[+t.dataset.a];if(s){CAP.scen=JSON.parse(JSON.stringify(s.sc));render()}},
 scencommit(){const sc=CAP.scen;const tm=selSet("pp2ct",teamList())[0]||"Platform team";if(sc.ctr>0)CAP.reqs.unshift({id:"RQ"+(CAP.reqs.length+1),title:sc.ctr+" contractors from the scenario",team:tm,role:"Engineer or architect",kind:"contractor",skills:[],fte:sc.ctr*sc.ctrH/40,from:isoOfWk(sc.from),to:isoOfWk(Math.min(NWK-1,sc.from+sc.weeks)),status:"Submitted",by:"Omar Hamid",why:"From a capacity scenario.",at:"2026-10-07"});(sc.proj||[]).forEach(id=>{const d=DEMAND.find(x=>x.id===id);if(d)(d.res||[]).forEach(([team,f])=>CAP.reqs.unshift({id:"RQ"+(CAP.reqs.length+1),title:"Capacity for "+d.n,team,role:"Engineer or architect",kind:"any",skills:[],fte:f,from:isoOfWk(Math.round(d.m0*4.35)),to:isoOfWk(Math.min(NWK-1,Math.round((d.m0+d.mo)*4.35))),status:"Submitted",by:"Omar Hamid",why:"Scenario for "+d.n,at:"2026-10-07",proj:d.id}))});bumpMv();audit("committed scenario to resource requests","");toast("Requests created. See Bench and requests.","good");st.tab.ppl_cap=7;render()},
 plate(t){const [n,id]=t.dataset.a.split("|");const it=plate(n).find(x=>String(x.id)===id);if(it&&it.go)it.go()},
 gocap(t){CAP.person=t.dataset.a||null;st.tab.ppl_cap=3;closeDrawer();go("ppl_cap")}});
document.addEventListener("input",e=>{const t=e.target.closest("[data-pp2-pq]");if(!t)return;const q=t.value.trim().toLowerCase();const box=document.getElementById("pp2PSug");if(!box)return;if(q.length<2){box.innerHTML="";return}const L=DIR.filter(d=>(d.name+" "+d.role+" "+d.team+" "+(d.skills||[]).join(" ")).toLowerCase().includes(q)).slice(0,8);box.innerHTML=L.map(d=>`<button type="button" role="option" data-pp2-act="gocap" data-a="${E(d.name)}">${avatar(d,{size:26})}<span><b>${E(d.name)}</b> <small>${E(roleOf(d))} · ${E(d.team||"")}</small></span></button>`).join("")||'<span class="muted small" style="padding:8px">No matches</span>'});
document.addEventListener("change",e=>{const t=e.target.closest("[data-pp2-wt]");if(t){CAP.wt=t.value;render()}});
/* Person 360: capacity outlook */
P360_TABS.push({label:"Capacity outlook",fn:r=>{if(r.kind==="msp"&&!MSPH[r.name])return "<p class=\"muted\">No hours are planned for this provider.</p>";const m=PM(r.name),v=verdict(r.name);return `<div class="pp2-verdict ${v.cls}"><div class="eyebrow">Can ${E(first(r.name))} handle more?</div><div class="pp2-vh">${v.head}</div><p>${v.tx}</p></div>${weekStack(m,0,11)}${typeLeg()}<div class="row" style="margin-top:12px"><button class="btn primary" data-pp2-act="gocap" data-a="${E(r.name)}">Everything on their plate</button><button class="btn" data-pp2-act="assign" data-a="">Assign work</button></div>`}});
WORK.push({kind:"Resource requests",tag:"RES",fn:n=>CAP.reqs.filter(q=>q.by===n&&q.status!=="Filled").map(q=>({id:q.id,t:q.title,sub:q.status+" · "+q.fte+" FTE",due:DT(q.from),st:"info",hrs:.25,go:()=>{st.tab.ppl_cap=7;go("ppl_cap")}}))});
